content.content:
1	//! Embedded Freenet node (Android-only at runtime, portable at the
2	//! type level so host `cargo test` can exercise the no-JNI fallback
3	//! paths).
4	//!
5	//! On Android, `start_embedded_node` spawns a dedicated tokio
6	//! multi-thread runtime on a background OS thread and drives the
7	//! freenet node's network-mode event loop on it. The node binds its
8	//! WebSocket client API at the default `127.0.0.1:7509`; River's
9	//! `ConnectionManager` (native impl in
10	//! `freenet_api/connection_manager.rs`) connects to that endpoint.
11	//!
12	//! The node is *separate* from the Dioxus runtime — it owns its own
13	//! tokio reactor so the UI's event loop isn't sharing scheduling
14	//! pressure with wasmtime contract execution, and so that long-lived
15	//! node tasks (peer connection recv loops, transport drivers) don't
16	//! have to be `'static` against the Dioxus scope.
17	//!
18	//! **Network mode, not Local.** A Local-mode node only serves what's
19	//! been PUT to its own stores — Android users could create their own
20	//! rooms but could not join any room shared via invitation link,
21	//! because the network state never reaches their device. Network
22	//! mode makes the device a real Freenet peer that fetches contracts
23	//! and states through peers and gateways. See
24	//! `openspec/changes/android-bundled-node/design.md` decision #2 for
25	//! the full rationale and the mobile-NAT risks.
26	//!
27	//! Remaining caveats (tracked in the OpenSpec change's tasks.md):
28	//! - No foreground service yet — Android may kill the process when
29	//!   the app backgrounds (tasks 5.x).
30	//!
31	//! On non-Android targets, `start_embedded_node` is a no-op stub so
32	//! the module compiles for host `cargo check` / `cargo test` without
33	//! pulling in freenet, tokio, jni, or ndk-context.
34	
35	use std::path::PathBuf;
36	use std::sync::OnceLock;
37	
38	/// Synthetic auth token registered with the embedded node's
39	/// `OriginContractMap` at startup, surfaced here so the UI's loopback
40	/// WebSocket dial can attach it as `?authToken=…`.
41	///
42	/// **Why this exists.** The chat-delegate's `check_origin` rejects any
43	/// `DelegateRequest::ApplicationMessage` whose `MessageOrigin` is
44	/// `None` with `"missing message origin"`. On the web build the gateway
45	/// shell injects `window.__FREENET_AUTH_TOKEN__`, and the WS handler
46	/// looks the token up in a map populated when the shell HTML was served
47	/// to mint the page's contract origin. On Android the UI loads via wry's
48	/// custom protocol, never goes through a gateway shell, and would
49	/// otherwise dial the loopback WS anonymously — every delegate save
50	/// times out and the room is lost on restart.
51	///
52	/// We close that gap by pre-registering a random token under River's
53	/// **published web-container contract id** (so the attested origin
54	/// matches what web clients send) in `serve_client_api_with_listener_and_contracts`'s
55	/// returned map, then publishing the token here for
56	/// `connection_manager` to pick up. `OnceLock` because the node starts
57	/// exactly once per process and the token is immutable thereafter.
58	pub static EMBEDDED_AUTH_TOKEN: OnceLock<String> = OnceLock::new();
59	
60	/// Hardcoded fallback for the embedded Freenet node's storage dir.
61	///
62	/// Matches the package id in `ui/Dioxus.toml` (`org.freenet.river`).
63	/// On a real device the runtime path comes from
64	/// `Context.getFilesDir()` via JNI ([`android_files_dir`]) — this
65	/// constant is only used when the JNI lookup fails (emulator without
66	/// an attached Activity, unusual launch path, etc.) so the node can
67	/// still boot rather than aborting.
68	pub(crate) const FREENET_DATA_DIR_FALLBACK: &str =
69	    "/data/data/org.freenet.river/files/freenet";
70	
71	/// Resolve the app's private files dir at runtime via JNI.
72	///
73	/// Walks the standard Android startup handles:
74	/// 1. `ndk_context::android_context()` exposes the `JavaVM` + the
75	///    activity's `Context` jobject, published by ndk-glue / wry / tao
76	///    during native startup.
77	/// 2. Attach the current thread to the VM.
78	/// 3. Call `Context.getFilesDir() -> java/io/File`.
79	/// 4. Call `File.getAbsolutePath() -> java/lang/String`.
80	/// 5. Decode the Java string to a Rust `String` and join `"freenet"`
81	///    onto it, giving the node its own subdirectory under the app's
82	///    private files area.
83	///
84	/// Returns `None` on any JNI failure (ndk-context not populated, VM
85	/// attach failure, `NoSuchMethodError`) AND on every non-Android
86	/// target. Callers fall back to [`FREENET_DATA_DIR_FALLBACK`] and
87	/// emit a `warn!` so the failure is visible in logcat.
88	#[cfg(target_os = "android")]
89	pub(crate) fn android_files_dir() -> Option<PathBuf> {
90	    use jni::objects::{JObject, JString};
91	    use jni::JavaVM;
92	
93	    let ctx = ndk_context::android_context();
94	    let vm = unsafe { JavaVM::from_raw(ctx.vm().cast()) }.ok()?;
95	    let activity = unsafe { JObject::from_raw(ctx.context().cast()) };
96	
97	    let mut env = vm.attach_current_thread().ok()?;
98	
99	    // Context.getFilesDir() -> java/io/File
100	    let files_dir = env
101	        .call_method(&activity, "getFilesDir", "()Ljava/io/File;", &[])
102	        .ok()?
103	        .l()
104	        .ok()?;
105	
106	    // File.getAbsolutePath() -> java/lang/String
107	    let path_jstr = env
108	        .call_method(&files_dir, "getAbsolutePath", "()Ljava/lang/String;", &[])
109	        .ok()?
110	        .l()
111	        .ok()?;
112	
113	    let path_jstr: JString = path_jstr.into();
114	    let rust_path: String = env.get_string(&path_jstr).ok()?.into();
115	
116	    Some(PathBuf::from(rust_path).join("freenet"))
117	}
118	
119	/// Host stub: no Activity, no JNI, always return `None` so the
120	/// caller falls back to [`FREENET_DATA_DIR_FALLBACK`].
121	#[cfg(not(target_os = "android"))]
122	pub(crate) fn android_files_dir() -> Option<PathBuf> {
123	    None
124	}
125	
126	/// Compute the node's storage dir, with the JNI lookup tried first
127	/// and a fall-back to the hardcoded package-private path on failure.
128	pub(crate) fn resolve_data_dir() -> PathBuf {
129	    android_files_dir().unwrap_or_else(|| PathBuf::from(FREENET_DATA_DIR_FALLBACK))
130	}
131	
132	#[cfg(target_os = "android")]
133	mod android {
134	    use super::*;
135	    use std::path::Path;
136	    use std::sync::Mutex;
137	
138	    use dioxus::logger::tracing::{error, info, warn};
139	    use freenet::client_events::{AuthToken, ClientId};
140	    use freenet::config::ConfigArgs;
141	    use freenet::local_node::{NodeConfig, OperationMode};
142	    use freenet::server::{
143	        OriginContract, serve_client_api_with_listener_and_contracts,
144	    };
145	    use freenet_stdlib::prelude::ContractInstanceId;
146	    use tokio::sync::oneshot;
147	
148	    /// Base58 contract id of River's published web-container contract
149	    /// (`REDACTED`, the same id
150	    /// `published-contract/contract-id.txt` records). We attest this id
151	    /// to the chat delegate as the embedded UI's origin so the
152	    /// delegate's per-origin storage namespace (`signing_key:{origin}:…`,
153	    /// `outbound_dms:{origin}:…`, etc.) matches what web clients use —
154	    /// keeps the namespace coherent if delegate state ever syncs across
155	    /// devices, and keeps the chat-delegate's `check_origin` guard
156	    /// satisfied. If the published web-container parameters ever shift
157	    /// the contract id, update both files in lockstep.
158	    const WEB_CONTAINER_CONTRACT_ID: &str =
159	        "REDACTED";
160	
161	    /// Park for the lifetime of the process so that
162	    /// `Java_dev_dioxus_main_RiverNodeService_nativeOnServiceStop` can
163	    /// fire the oneshot from a foreign thread (the JNI callback runs on
164	    /// whatever thread the Android service is destroyed on, NOT the
165	    /// freenet-worker tokio runtime).
166	    ///
167	    /// Populated once `run_node()` reaches its `select!` point and parks
168	    /// the receiver. If the user hits Home and then the foreground
169	    /// service is destroyed before the node has finished booting,
170	    /// `nativeOnServiceStop` finds `None` in the Mutex and short-circuits —
171	    /// the process will be killed by the OS anyway and there's nothing
172	    /// for us to gracefully drop.
173	    static SHUTDOWN_TX: Mutex<Option<oneshot::Sender<()>>> = Mutex::new(None);
174	
175	    /// Fallback `gateways.toml` and its referenced X25519 public-key files,
176	    /// snapshotted from `https://freenet.org/keys/` at release time.
177	    ///
178	    /// Used only on first launch IF freenet's auto-fetch from
179	    /// `freenet.org` fails (offline, DNS blocked, etc.). Once the live
180	    /// fetch succeeds, freenet overwrites `config_dir/gateways.toml` with
181	    /// the freshly-fetched paths and these fallbacks are unused. See
182	    /// `vendor/freenet/src/config.rs::load_gateways_from_index` for the
183	    /// canonical fetch behaviour and the local-cache fallback path that
184	    /// reads this file on retry.
185	    ///
186	    /// Refresh procedure: re-fetch from
187	    /// `https://freenet.org/keys/{gateways.toml,public.nova.gw.pem,public.vega.gw.pem}`
188	    /// when cutting a release, replace the three files under
189	    /// `ui/assets/freenet/`, and verify a debug APK can bootstrap with
190	    /// `freenet.org` DNS blocked.
191	    const FALLBACK_GATEWAYS_TOML: &[u8] = include_bytes!("../assets/freenet/gateways.toml");
192	    const FALLBACK_NOVA_PUBKEY: &[u8] = include_bytes!("../assets/freenet/public.nova.gw.pem");
193	    const FALLBACK_VEGA_PUBKEY: &[u8] = include_bytes!("../assets/freenet/public.vega.gw.pem");
194	
195	    /// Boot the in-process Freenet node on a dedicated background thread.
196	    ///
197	    /// Returns immediately; the node runs for the lifetime of the process
198	    /// (or until an unrecoverable error, which is logged). Safe to call
199	    /// multiple times — guarded by a one-shot.
200	    pub fn start_embedded_node() {
201	        use std::sync::Once;
202	        static START: Once = Once::new();
203	        START.call_once(|| {
204	            info!("Spawning embedded Freenet node thread");
205	            let handle = std::thread::Builder::new()
206	                .name("freenet-embedded".into())
207	                .stack_size(4 * 1024 * 1024) // wasmtime needs >stack default
208	                .spawn(|| {
209	                    let rt = match tokio::runtime::Builder::new_multi_thread()
210	                        .enable_all()
211	                        .thread_name("freenet-worker")
212	                        .build()
213	                    {
214	                        Ok(rt) => rt,
215	                        Err(e) => {
216	                            error!("Failed to build tokio runtime for embedded node: {e}");
217	                            return;
218	                        }
219	                    };
220	                    rt.block_on(async move {
221	                        match run_node().await {
222	                            Ok(()) => info!("Embedded Freenet node exited cleanly"),
223	                            Err(e) => {
224	                                error!("Embedded Freenet node exited with error: {e:?}")
225	                            }
226	                        }
227	                    });
228	                });
229	            if let Err(e) = handle {
230	                error!("Failed to spawn freenet-embedded thread: {e}");
231	            }
232	        });
233	    }
234	
235	    /// Build a network-mode `Config` and drive the node's event loop.
236	    ///
237	    /// Mirrors `freenet/src/bin/freenet.rs::run_network`:
238	    ///   1. `serve_client_api` binds the loopback WebSocket the UI dials.
239	    ///   2. `NodeConfig::new` loads peer-state config (gateway list,
240	    ///      peer id, etc.).
241	    ///   3. `node_config.build(clients)` wires the client API into the
242	    ///      node.
243	    ///   4. `freenet::run_network_node` drives the event loop forever.
244	    async fn run_node() -> anyhow::Result<()> {
245	        let data_dir = resolve_data_dir();
246	        if android_files_dir().is_none() {
247	            warn!(
248	                "JNI lookup for Context.getFilesDir() failed; falling back to {}. \
249	                 The node will still try to boot, but if the package id ever drifts \
250	                 from `org.freenet.river` (see ui/Dioxus.toml) writes will land in \
251	                 the wrong place. This usually means an emulator launched without \
252	                 an attached Activity, or the ndk-context handles weren't populated.",
253	                FREENET_DATA_DIR_FALLBACK
254	            );
255	        }
256	        if let Err(e) = std::fs::create_dir_all(&data_dir) {
257	            warn!("Could not create node data dir {data_dir:?}: {e}");
258	            // Continue anyway — freenet's own setup will surface the
259	            // error through anyhow with full context.
260	        }
261	
262	        // Stage the fallback `gateways.toml` + PEMs into the node's
263	        // config dir BEFORE `args.build()`, because `ConfigArgs::build`
264	        // is itself what loads the gateway list — if neither a live
265	        // fetch nor a local cache produces one, build() returns
266	        // `Cannot initialize node without gateways` and we never even
267	        // get a `Config` to inspect. The config dir layout is fixed
268	        // (see vendor/freenet/src/config.rs::ConfigPaths::build):
269	        //
270	        //   config_dir  = data_dir            (the path we set above)
271	        //   secrets_dir = data_dir.join("secrets")
272	        //
273	        // Best-effort: failures are logged but don't abort startup,
274	        // because freenet's own first-launch HTTPS fetch from
275	        // `freenet.org` is the primary path. The bundled fallback
276	        // only matters when first launch is offline (no network).
277	        let config_dir = data_dir.clone();
278	        let secrets_dir = data_dir.join("secrets");
279	        if let Err(e) = stage_fallback_gateways(&config_dir, &secrets_dir) {
280	            warn!("Could not stage fallback gateways: {e}. Live fetch will be attempted.");
281	        }
282	
283	        let mut args = ConfigArgs {
284	            mode: Some(OperationMode::Network),
285	            ..ConfigArgs::default()
286	        };
287	        args.config_paths.config_dir = Some(data_dir.clone());
288	        args.config_paths.data_dir = Some(data_dir.clone());
289	        args.config_paths.log_dir = Some(data_dir.join("logs"));
290	
291	        info!("Building freenet network Config at {:?}", data_dir);
292	        let config = args.build().await?;
293	        let ws_socket = config.ws_api.clone();
294	
295	        info!("Starting client API on {:?}", ws_socket.address);
296	        let clients = serve_client_api(ws_socket)
297	            .await
298	            .map_err(|e| anyhow::anyhow!("failed to start client API: {e}"))?;
299	
300	        info!("Initialising NodeConfig (loads gateways.toml, derives peer id)");
301	        let node_config = NodeConfig::new(config).await?;
302	
303	        info!("Building network node");
304	        let node = node_config.build(clients).await?;
305	
306	        // Park the shutdown receiver before entering the event loop so
307	        // that a service-stop intent landing the instant after the
308	        // notification appears can still tear us down. The lock is held
309	        // only across the assignment.
310	        let (tx, shutdown_rx) = oneshot::channel::<()>();
311	        *SHUTDOWN_TX.lock().expect("SHUTDOWN_TX poisoned") = Some(tx);
312	
313	        info!("Running network node event loop (with foreground-service shutdown hook)");
314	        tokio::select! {
315	            res = freenet::run_network_node(node) => {
316	                res?;
317	            }
318	            _ = shutdown_rx => {
319	                info!("Embedded node shutdown requested by RiverNodeService.onDestroy");
320	            }
321	        }
322	        Ok(())
323	    }
324	
325	    /// JNI hook invoked from `RiverNodeService.onDestroy()` (see
326	    /// `ui/android/kotlin/dev/dioxus/main/RiverNodeService.kt`).
327	    ///
328	    /// Fires the parked oneshot so the freenet-worker tokio runtime
329	    /// drops the network node + transport drivers in an orderly fashion
330	    /// rather than being SIGKILL'd by Android. Best-effort: if the node
331	    /// hasn't reached `run_network_node` yet (e.g. user mashed Stop
332	    /// during boot), the sender is `None` and we no-op.
333	    ///
334	    /// JNI ABI: the function name must match the fully-qualified
335	    /// Java/Kotlin class + method name, with `.` replaced by `_`. Any
336	    /// rename on either side must be made in lock-step.
337	    ///
338	    /// Signature uses the raw `jni::sys` C types so we don't carry a
339	    /// `JNIEnv<'local>` lifetime through a `#[no_mangle] extern "system"`
340	    /// — we never call back into the JVM from this function, so the
341	    /// raw pointers are all we need.
342	    #[no_mangle]
343	    pub unsafe extern "system" fn Java_dev_dioxus_main_RiverNodeService_nativeOnServiceStop(
344	        _env: *mut jni::sys::JNIEnv,
345	        _class: jni::sys::jclass,
346	    ) {
347	        match SHUTDOWN_TX.lock() {
348	            Ok(mut slot) => match slot.take() {
349	                Some(tx) => {
350	                    if tx.send(()).is_err() {
351	                        warn!("Embedded node already gone — shutdown signal dropped");
352	                    } else {
353	                        info!("Shutdown signal sent to embedded node");
354	                    }
355	                }
356	                None => {
357	                    info!(
358	                        "RiverNodeService.onDestroy fired before embedded node reached \
359	                         the event loop — nothing to signal"
360	                    );
361	                }
362	            },
363	            Err(e) => {
364	                error!("SHUTDOWN_TX mutex poisoned: {e}");
365	            }
366	        }
367	    }
368	
369	    /// Stage the bundled fallback `gateways.toml` + PEMs into
370	    /// `config_dir` and `secrets_dir`, ONLY if
371	    /// `config_dir/gateways.toml` doesn't already exist.
372	    ///
373	    /// Freenet's [`NodeConfig::new`] tries the live remote fetch
374	    /// first; on success, it overwrites `config_dir/gateways.toml`
375	    /// (and the PEMs in `secrets_dir`) with the freshly-fetched
376	    /// copy. On failure, it falls back to parsing whatever is
377	    /// already at `config_dir/gateways.toml`. By pre-staging the
378	    /// bundled fallback when that file is absent, we guarantee an
379	    /// offline first-launch still has a valid gateways list to
380	    /// parse — without it the node would error out with `Cannot
381	    /// initialize node without gateways`.
382	    ///
383	    /// We do NOT overwrite an existing `gateways.toml`: any file
384	    /// already at that path is freenet's own cache from a prior
385	    /// successful fetch and is at least as fresh as our bundle.
386	    ///
387	    /// The bundled PEMs match the snapshot in `ui/assets/freenet/`.
388	    /// If the live fetch later succeeds, freenet overwrites the
389	    /// same PEM filenames in `secrets_dir` with the fresh content —
390	    /// our stale bytes don't linger.
391	    fn stage_fallback_gateways(config_dir: &Path, secrets_dir: &Path) -> std::io::Result<()> {
392	        let gateways_file = config_dir.join("gateways.toml");
393	        if gateways_file.exists() {
394	            return Ok(());
395	        }
396	        std::fs::create_dir_all(config_dir)?;
397	        std::fs::create_dir_all(secrets_dir)?;
398	
399	        let nova_path = secrets_dir.join("public.nova.gw.pem");
400	        let vega_path = secrets_dir.join("public.vega.gw.pem");
401	        std::fs::write(&nova_path, FALLBACK_NOVA_PUBKEY)?;
402	        std::fs::write(&vega_path, FALLBACK_VEGA_PUBKEY)?;
403	
404	        // Build the TOML with absolute paths. Freenet's local-cache
405	        // parser deserializes `public_key` straight into a `PathBuf`
406	        // and opens the file with no further path resolution;
407	        // relative paths would be resolved against the CWD, which
408	        // is undefined on Android.
409	        let toml = format!(
410	            "# Bundled fallback (used because freenet's live fetch failed).\n\
411	             [[gateways]]\n\
412	             public_key = \"{}\"\n\
413	             [gateways.address]\n\
414	             hostname = \"nova.locut.us:31337\"\n\
415	             \n\
416	             [[gateways]]\n\
417	             public_key = \"{}\"\n\
418	             [gateways.address]\n\
419	             hostname = \"vega.locut.us:31337\"\n",
420	            nova_path.display(),
421	            vega_path.display(),
422	        );
423	        std::fs::write(&gateways_file, toml)?;
424	
425	        info!(
426	            "Staged fallback gateways.toml + 2 PEMs at {:?} ({} bytes bundled)",
427	            gateways_file,
428	            FALLBACK_GATEWAYS_TOML.len(),
429	        );
430	        Ok(())
431	    }
432	}
433	
434	#[cfg(target_os = "android")]
435	pub use android::start_embedded_node;
436	
437	/// Non-Android stub. The Android startup path in `App()` is itself
438	/// `cfg(target_os = "android")`-gated, so this stub is unreachable
439	/// in practice — but exposing it lets the module compile for host
440	/// `cargo check` / `cargo test` without dragging in freenet, tokio,
441	/// jni, or ndk-context.
442	#[cfg(not(target_os = "android"))]
443	#[allow(dead_code)]
444	pub fn start_embedded_node() {}
445	
446	#[cfg(test)]
447	mod tests {
448	    use super::*;
449	
450	    #[test]
451	    fn fallback_path_targets_known_package_id() {
452	        // The hardcoded fallback must point at the package id River
453	        // declares in `ui/Dioxus.toml` — if that identifier ever
454	        // changes, this constant has to follow or the bundled node
455	        // will write to a directory Android won't grant access to.
456	        assert!(
457	            FREENET_DATA_DIR_FALLBACK.contains("/org.freenet.river/"),
458	            "fallback {FREENET_DATA_DIR_FALLBACK} no longer targets org.freenet.river"
459	        );
460	        assert!(
461	            FREENET_DATA_DIR_FALLBACK.ends_with("/freenet"),
462	            "fallback {FREENET_DATA_DIR_FALLBACK} must end with /freenet \
463	             so the node has its own subdir under the app's private files area"
464	        );
465	    }
466	
467	    /// On non-Android targets `android_files_dir` is the no-op stub,
468	    /// so `resolve_data_dir` MUST return the hardcoded fallback.
469	    /// Gated to non-android because on a real device the JNI lookup
470	    /// succeeds and returns a different (real) path — the assertion
471	    /// would not hold there.
472	    #[cfg(not(target_os = "android"))]
473	    #[test]
474	    fn resolve_data_dir_returns_fallback_off_device() {
475	        assert!(android_files_dir().is_none(), "host stub must return None");
476	        let dir = resolve_data_dir();
477	        assert_eq!(dir, PathBuf::from(FREENET_DATA_DIR_FALLBACK));
478	    }
479	}
