58	// Tracks which rooms need to be synced due to USER actions (not network updates)
59	// This prevents infinite loops where network responses trigger more syncs
60	pub static NEEDS_SYNC: GlobalSignal<std::collections::HashSet<VerifyingKey>> =
61	    Global::new(std::collections::HashSet::new);
62	
63	/// Mark a room as needing sync, deferred via setTimeout(0).
64	///
65	/// IMPORTANT: Writing to NEEDS_SYNC triggers a Dioxus use_effect synchronously,
66	/// which cascades into ProcessRooms → ROOMS.read() and other signal reads.
67	/// If called while any signal is borrowed, this causes a RefCell re-entrant
68	/// borrow panic in WASM.
69	///
70	/// We use setTimeout(0) instead of spawn_local because spawn_local runs within
71	/// wasm-bindgen-futures' task scheduler, which may itself hold a RefCell borrow
72	/// when polling tasks. setTimeout(0) breaks out of the WASM call stack entirely,
73	/// ensuring the write happens in a completely clean execution context.
74	pub fn mark_needs_sync(room_key: ed25519_dalek::VerifyingKey) {
75	    crate::util::defer(move || {
76	        NEEDS_SYNC.write().insert(room_key);
77	    });
78	}
