83	// Build metadata from build.rs
84	const BUILD_TIMESTAMP: &str = env!("BUILD_TIMESTAMP_ISO");
85	const GIT_COMMIT: &str = env!("GIT_COMMIT_HASH");
86	
87	#[component]
88	pub fn App() -> Element {
89	    info!(
90	        "River UI loaded - Built: {} | Commit: {}",
91	        BUILD_TIMESTAMP, GIT_COMMIT
92	    );
93	
94	    // Android: boot the in-process Freenet node BEFORE the synchronizer
95	    // dials loopback. `start_embedded_node` is `Once`-guarded, so calling
96	    // it on every App re-render is safe. The structured log line makes
97	    // the boot sequence visible under `adb logcat -s River:V`:
98	    // node start → synchronizer init → first connect.
99	    #[cfg(target_os = "android")]
100	    {
101	        info!("android: starting embedded Freenet node before synchronizer init");
102	        crate::node_runtime::start_embedded_node();
103	    }
104	
105	    // Capture the Dioxus runtime for use in defer()/setTimeout callbacks.
106	    // Must be called from within a Dioxus component where the runtime is active.
107	    crate::util::capture_runtime();
108	
109	    // Install the document-level click interceptor that catches
110	    // in-page invite-URL anchor clicks and routes them through the
111	    // in-app receive-invitation flow instead of letting the browser
112	    // navigate the iframe in place (Ivvor's "lockup" report,
113	    // 2026-05-16). Safe to call on every re-render — idempotent.
114	    crate::components::invite_click_interceptor::install_invite_click_interceptor();
115	
116	    let mut receive_invitation = use_signal(|| None::<Invitation>);
117	
118	    // Bridge the click interceptor's `INTERCEPTED_INVITATION_CODE` global
119	    // into the local `receive_invitation` signal that drives
120	    // `ReceiveInvitationModal`. Same gate as the URL-bar flow below: we
121	    // ignore codes that have already been processed in this browser
122	    // (so a click on the same link twice doesn't reopen the modal
123	    // after acceptance/dismiss).
124	    //
125	    // Per AGENTS.md "Dioxus WASM Signal Safety Rules":
126	    // * `.try_read()` (not `.read()`) — the interceptor writes from a
127	    //   deferred JS callback whose Drop fires subscriber notifications
128	    //   synchronously; a non-fallible read while the write guard is
129	    //   still alive panics on Firefox mobile.
130	    // * Synchronous clear (not `defer()`) — `use_effect` that defers
131	    //   clearing a signal it subscribes to triggers a re-fire loop
132	    //   (effect re-runs because `receive_invitation.set` mutates a
133	    //   sibling signal → re-render → effect observes the same Some →
134	    //   processes again). Project rule "Never defer signal clears in
135	    //   `use_effect`" is explicit about this.
136	    use_effect(move || {
137	        let pending = {
138	            let g = crate::components::invite_click_interceptor::INTERCEPTED_INVITATION_CODE
139	                .try_read()
140	                .ok();
141	            g.and_then(|opt| opt.clone())
142	        };
143	        let Some(code) = pending else {
144	            return;
145	        };
146	        // Synchronous clear BEFORE processing, so the re-render
147	        // triggered by `receive_invitation.set(...)` below doesn't
148	        // observe the same Some value and re-fire this effect.
149	        *crate::components::invite_click_interceptor::INTERCEPTED_INVITATION_CODE.write() = None;
150	        match Invitation::from_encoded_string(&code) {
151	            Ok(invitation) => {
152	                let fingerprint = invitation.to_encoded_string();
153	                if is_invitation_processed(&fingerprint) {
154	                    debug!("Intercepted invite click already processed; ignoring");
155	                } else {
156	                    info!("Intercepted invite link click: opening modal in place");
157	                    save_invitation_to_storage(&invitation);
158	                    receive_invitation.set(Some(invitation));
159	                }
160	            }
161	            Err(e) => {
162	                warn!(
163	                    "Intercepted invite click had unparseable code: {} (len {})",
164	                    e,
165	                    code.len()
166	                );
167	            }
168	        }
169	    });
170	
171	    // Get auth token from window global (injected by Freenet gateway)
172	    // This is synchronous - no network request needed
173	    get_auth_token_from_window();
174	
175	    // Start synchronizer - auth token is already available.
176	    //
177	    // Cross-platform: on web, `connection_manager.rs`'s wasm `imp` uses
178	    // `web_sys::WebSocket`; on native (Android/desktop), the non-wasm `imp`
179	    // uses `tokio-tungstenite` and `freenet-stdlib`'s `regular` WebApi.
180	    // `crate::platform::spawn_local` picks the right runtime per target.
181	    spawn_local(async {
182	        debug!("Starting FreenetSynchronizer from App component");
183	        // Note: The synchronizer will set up the chat delegate after connection is established
184	        let mut synchronizer = SYNCHRONIZER.write();
185	        synchronizer.start().await;
186	    });
187	
188	    // Check URL for invitation parameter, then fall back to localStorage.
189	    //
190	    // The URL cannot be rewritten by the iframe: `history.replaceState`
191	    // requires same-origin and the gateway iframe runs in an opaque origin
192	    // (`sandbox="allow-scripts allow-forms allow-popups"`, no
193	    // `allow-same-origin`). Instead, the user's accept/decline actions are
194	    // recorded as fingerprints in River's slice of the *top-level* URL hash
195	    // (`#river-processed=fp1,fp2,...`), which the gateway shell propagates
196	    // into the iframe on every load. The hash is updated via the shell's
197	    // postMessage bridge, which has same-origin access.
198	    //
199	    // The fingerprint is keyed off `Invitation::to_encoded_string()`
200	    // (canonical CBOR + base58, see `invitation_round_trip_is_byte_stable`
201	    // test) so URL-time and dismiss-time fingerprints match for the same
202	    // invitation. See issues #215 and #219.
203	    let mut found_invitation = false;
204	    if let Some(window) = window() {
205	        if let Ok(search) = window.location().search() {
206	            if let Ok(params) = web_sys::UrlSearchParams::new_with_str(&search) {
207	                if let Some(invitation_code) = params.get("invitation") {
208	                    if let Ok(invitation) = Invitation::from_encoded_string(&invitation_code) {
209	                        if is_invitation_processed(&invitation.to_encoded_string()) {
210	                            debug!(
211	                                "Skipping invitation in URL: already accepted or dismissed in this browser"
212	                            );
213	                        } else {
214	                            info!("Received invitation from URL: {:?}", invitation);
215	                            save_invitation_to_storage(&invitation);
216	                            receive_invitation.set(Some(invitation));
217	                            found_invitation = true;
218	                        }
219	                    }
220	
221	                    // Best-effort: remove the invitation parameter from the
222	                    // URL. Fails in the sandboxed iframe (opaque origin) but
223	                    // is still useful in non-sandboxed deployments such as
224	                    // dx-serve dev mode. The processed-hash fingerprint is
225	                    // the authoritative guard.
226	                    //
227	                    // Web-only: the History API has no analogue on the
228	                    // mobile (webview) renderer, where there is no URL bar
229	                    // to clean up. The processed-hash fingerprint guard above
230	                    // is what actually prevents re-presenting the invitation.
231	                    #[cfg(target_arch = "wasm32")]
232	                    {
233	                        params.delete("invitation");
234	                        let new_search = params.to_string().as_string().unwrap_or_default();
235	                        let new_url = if new_search.is_empty() {
236	                            window.location().pathname().unwrap_or_default()
237	                        } else {
238	                            format!(
239	                                "{}?{}",
240	                                window.location().pathname().unwrap_or_default(),
241	                                new_search
242	                            )
243	                        };
244	                        if let Ok(history) = window.history() {
245	                            if let Err(e) = history.replace_state_with_url(
246	                                &wasm_bindgen::JsValue::NULL,
247	                                "",
248	                                Some(&new_url),
249	                            ) {
250	                                debug!(
251	                                    "history.replaceState failed (likely sandboxed iframe): {:?}",
252	                                    e
253	                                );
254	                            }
255	                        }
256	                    }
257	                }
258	            }
259	        }
260	    }
261	
262	    // Bridge `PRESENT_INVITATION_REQUEST` (set by the DM-thread "Accept"
263	    // button on an invite-card DM) into the local `receive_invitation`
264	    // signal so `ReceiveInvitationModal` opens for in-app accepts the same
265	    // way it does for URL-bar accepts. Synchronous clear before the
266	    // `receive_invitation.set` follows the same rule as the click-
267	    // interceptor bridge above (AGENTS.md "Never defer signal clears in
268	    // use_effect").
269	    //
270	    // Gate on `is_invitation_processed` — without it, a previously-
271	    // accepted-then-LeaveRoom'd invitation re-presented via the DM
272	    // accept-card would pop the nickname-prompt modal again, which is
273	    // alarming for the user and forces them through the whole join
274	    // flow for a room they've already acted on (#279). The URL-bar
275	    // (line 192) and click-interceptor (line 141) paths already gate
276	    // on this; the DM-card bridge was the missing case.
277	    //
278	    // `try_read() -> Err` on the FIRST render is benign: the picker /
279	    // accept-card paths only ever write via `crate::util::defer()`, which
280	    // schedules a setTimeout(0) macrotask — the writer is never holding
281	    // the borrow at the moment this effect's first run reads. If a future
282	    // code path adds a NON-deferred writer to `PRESENT_INVITATION_REQUEST`,
283	    // the Err path can mask a present invitation for a render tick; pin
284	    // the "writes always defer" invariant via grep when extending callers.
285	    use_effect(move || {
286	        let pending = {
287	            let g = PRESENT_INVITATION_REQUEST.try_read().ok();
288	            g.and_then(|opt| opt.clone())
289	        };
290	        let Some(inv) = pending else {
291	            return;
292	        };
293	        *PRESENT_INVITATION_REQUEST.write() = None;
294	        let fingerprint = inv.to_encoded_string();
295	        if is_invitation_processed(&fingerprint) {
296	            // The user has already accepted or dismissed this
297	            // invitation in this browser. Don't re-open the modal:
298	            // either they're still a member (in which case the rail
299	            // already shows the room) or they've explicitly left and
300	            // re-presenting the join flow would be confusing. Silent
301	            // drop is the same handling the click-interceptor bridge
302	            // uses for the equivalent case.
303	            debug!(
304	                "In-app invitation accept ignored: already processed for room {:?}",
305	                MemberId::from(inv.room)
306	            );
307	            return;
308	        }
309	        info!(
310	            "In-app invitation accept: opening modal for room {:?}",
311	            MemberId::from(inv.room)
312	        );
313	        receive_invitation.set(Some(inv));
314	    });
315	
316	    // Recover invitation from localStorage if not found in URL (e.g. after
317	    // page reload before subscription completed). Skip if the user has
318	    // already acted on this invitation in a previous session. Without this
319	    // check, a reload mid-subscription re-opens the modal with a nickname
320	    // prompt even though the user already accepted, because PENDING_INVITES
321	    // is in-memory only.
322	    if !found_invitation {
323	        if let Some(invitation) = load_invitation_from_storage() {
324	            if is_invitation_processed(&invitation.to_encoded_string()) {
325	                debug!("Discarding recovered invitation: already processed");
326	                clear_invitation_from_storage();
327	            } else {
328	                info!("Recovered pending invitation from localStorage");
329	                receive_invitation.set(Some(invitation));
330	            }
331	        }
332	    }
333	
334	    // Seed DM_LAST_SEEN from the room state we just hydrated, so
335	    // previously-existing inbound DMs don't show up as unread on every
336	    // page load. We explicitly subscribe to ROOMS here so the effect
337	    // re-fires when the delegate finishes hydrating (`ROOMS` is empty on
338	    // synchronous first render). `seed_dm_last_seen_if_needed` is
339	    // internally gated by a one-shot flag — it ONLY seeds on the first
340	    // non-empty ROOMS observation, so subsequent inbound DMs are NOT
341	    // auto-seeded as already-read (Codex / Skeptical found that the
342	    // previous always-run version defeated the unread feature).
343	    use_effect(|| {
344	        // Touch ROOMS to register a subscription so this effect re-runs
345	        // on hydration.
346	        let _hydration_marker = ROOMS.try_read().map(|r| r.map.len()).unwrap_or(0);
347	        crate::components::direct_messages::seed_dm_last_seen_if_needed();
348	    });
349	
350	    // Outbound DM cache hygiene (#256): whenever ROOMS changes, drop
351	    // cached plaintext entries whose ciphertext is no longer present
352	    // in any room (recipient purged them, or per-pair-cap eviction in
353	    // the contract dropped them). The prune helper only writes when
354	    // something is actually removed, so it doesn't re-trigger itself.
355	    // We deliberately do NOT subscribe to OUTBOUND_DMS here — that
356	    // would loop, since prune mutates OUTBOUND_DMS.
357	    use_effect(|| {
358	        let _rooms_marker = ROOMS.try_read().map(|r| r.map.len()).unwrap_or(0);
359	        crate::components::app::chat_delegate::prune_outbound_dms_for_purges();
360	    });
361	
362	    #[cfg(not(feature = "no-sync"))]
363	    {
364	        // The synchronizer is now started in the auth token effect
365	
366	        // Watch NEEDS_SYNC signal for USER-initiated changes only
367	        // This prevents infinite loops from network response updates to ROOMS
368	        use_effect(move || {
369	            let rooms_needing_sync = NEEDS_SYNC.read().clone();
370	
371	            if !rooms_needing_sync.is_empty() {
372	                info!(
373	                    "User changes detected for {} rooms, triggering synchronization",
374	                    rooms_needing_sync.len()
375	                );
376	
377	                // Get all the data we need upfront to avoid nested borrows
378	                let message_sender = SYNCHRONIZER.read().get_message_sender();
379	                let has_rooms = ROOMS.try_read().map(|r| !r.map.is_empty()).unwrap_or(false);
380	                let has_invitations = !PENDING_INVITES.read().map.is_empty();
381	
382	                // Save and clear NEEDS_SYNC synchronously to prevent infinite re-runs
383	                // of this effect (the effect subscribes to NEEDS_SYNC, so deferring
384	                // the clear would cause a tight loop before setTimeout fires).
385	                let pending_rooms: Vec<_> = NEEDS_SYNC.read().iter().cloned().collect();
386	                NEEDS_SYNC.write().clear();
387	
388	                if has_rooms || has_invitations {
389	                    info!("Sending ProcessRooms message to synchronizer, has_rooms={}, has_invitations={}", has_rooms, has_invitations);
390	
391	                    if let Err(e) = message_sender.unbounded_send(SynchronizerMessage::ProcessRooms)
392	                    {
393	                        error!("Failed to send ProcessRooms message: {}", e);
394	                        // Re-insert rooms so they'll be retried on next trigger
395	                        for key in pending_rooms {
396	                            mark_needs_sync(key);
397	                        }
398	                    } else {
399	                        info!("ProcessRooms message sent successfully");
400	                    }
401	
402	                    // Use safe_spawn_local to avoid re-entrant borrow of
403	                    // wasm-bindgen-futures' task scheduler on Firefox mobile.
404	                    crate::util::safe_spawn_local(async {
405	                        if let Err(e) = chat_delegate::save_rooms_to_delegate().await {
406	                            error!("Failed to save rooms to delegate: {}", e);
407	                        }
408	                    });
409	                } else {
410	                    debug!("No rooms to synchronize");
411	                }
412	            }
413	        });
414	
415	        info!("FreenetSynchronizer setup complete");
416	    }
417	
418	    rsx! {
419	        // Favicon
420	        Link { rel: "icon", r#type: "image/svg+xml", href: asset!("/assets/river_logo.svg") }
421	        // Stylesheets
422	        Stylesheet { href: asset!("/assets/styles.css") }
423	        Stylesheet { href: asset!("/assets/main.css") }
424	
425	        // Main chat layout - grid with fixed sidebars and flexible center
426	        div { class: "flex bg-bg overflow-hidden app-root",
427	            // On desktop (md+): all three panels always visible
428	            // On mobile (<md): only the active panel is shown
429	            div {
430	                class: {
431	                    let is_rooms = *MOBILE_VIEW.read() == MobileView::Rooms;
432	                    if is_rooms { "w-full md:w-64 md:flex-shrink-0 flex" } else { "hidden md:w-64 md:flex-shrink-0 md:flex" }
433	                },
434	                RoomList {}
435	            }
436	            div {
437	                class: {
438	                    let is_chat = *MOBILE_VIEW.read() == MobileView::Chat;
439	                    if is_chat { "flex-1 flex min-w-0" } else { "hidden md:flex md:flex-1 md:min-w-0" }
440	                },
441	                Conversation {}
442	            }
443	            div {
444	                class: {
445	                    let is_members = *MOBILE_VIEW.read() == MobileView::Members;
446	                    if is_members { "w-full md:w-56 md:flex-shrink-0 flex" } else { "hidden md:w-56 md:flex-shrink-0 md:flex" }
447	                },
448	                MemberList {}
449	            }
450	        }
451	        EditRoomModal {}
452	        MemberInfoModal {}
453	        CreateRoomModal {}
454	        DmThreadModal {}
455	        InviteViaDmPickerModal {}
456	        ReceiveInvitationModal {
457	            invitation: receive_invitation
458	        }
459	        DocumentTitleUpdater {}
460	    }
461	}
