22	// Custom implementation for getrandom when targeting wasm32-unknown-unknown
23	#[cfg(all(target_arch = "wasm32", target_os = "unknown"))]
24	#[no_mangle]
25	unsafe extern "Rust" fn __getrandom_v02_custom(
26	    dest: *mut u8,
27	    len: usize,
28	) -> Result<(), getrandom::Error> {
29	    use std::num::NonZeroU32;
30	    use web_sys::window;
31	
32	    // Get the window object
33	    let window = window().ok_or_else(|| getrandom::Error::from(NonZeroU32::new(1).unwrap()))?;
34	
35	    // Get the crypto object directly from window
36	    let crypto = window
37	        .crypto()
38	        .map_err(|_| getrandom::Error::from(NonZeroU32::new(1).unwrap()))?;
39	
40	    // Create a buffer to hold the random bytes
41	    let mut buffer = vec![0u8; len];
42	
43	    // Fill the buffer with random values
44	    match crypto.get_random_values_with_u8_array(&mut buffer) {
45	        Ok(_) => {
46	            // Copy the random bytes to the destination buffer
47	            let dest_slice = core::slice::from_raw_parts_mut(dest, len);
48	            dest_slice.copy_from_slice(&buffer);
49	            Ok(())
50	        }
51	        Err(_) => Err(getrandom::Error::from(NonZeroU32::new(1).unwrap())),
